const user = $('POST /v2/user/info/').item.json.data.user;
const videoResult = $input.first();
const videoFailed = !!videoResult.json.error && !videoResult.json.data;
const videos = (!videoFailed && videoResult.json.data && videoResult.json.data.videos) || [];

const since = Math.floor(Date.now() / 1000) - 30 * 24 * 3600;
const recent = videos.filter((v) => v.create_time >= since);
const totalViews = recent.reduce((sum, v) => sum + (v.view_count || 0), 0);

return [{
  json: {
    platform: 'tiktok',
    account_id: user.open_id,
    account_name: user.display_name,
    followers_count: user.follower_count ?? null,
    views_recent_30d: recent.length ? totalViews : null,
    views_average: recent.length ? Math.round(totalViews / recent.length) : null,
    account_status: null
  }
}];
